'use client';

import React from 'react';
import { X, Clock, Train as TrainIcon } from 'lucide-react';
import { Train } from '../data/trainData';

interface TrainRouteModalProps { train: Train | null; onClose: () => void; }

export const TrainRouteModal: React.FC<TrainRouteModalProps> = ({ train, onClose }) => {
  if (!train) return null;
  return (
    <div className="modal-overlay">
      <div className="relative w-full max-w-2xl overflow-hidden rounded-3xl border border-stone-200 bg-white shadow-2xl animate-scale-in">
        <div className="flex items-center justify-between border-b border-stone-100 bg-stone-50/50 px-6 py-5">
          <div className="flex items-center gap-4">
            <div className="grid h-10 w-10 place-items-center rounded-xl bg-gradient-to-br from-orange-500 to-orange-600 text-white shadow-lg shadow-orange-500/20">
              <TrainIcon className="h-5 w-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="font-bold text-stone-900 text-lg">{train.name}</h3>
                <span className="rounded-lg bg-orange-50 px-2.5 py-1 text-xs font-bold text-orange-700 border border-orange-200">{train.number}</span>
              </div>
              <p className="text-xs text-stone-500 mt-0.5">Full Route • {train.duration}</p>
            </div>
          </div>
          <button onClick={onClose} className="rounded-xl bg-white p-2 text-stone-400 hover:text-stone-700 border border-stone-200 hover:border-stone-300 transition-all">
            <X className="h-5 w-5" />
          </button>
        </div>
        <div className="max-h-[60vh] overflow-y-auto p-6 space-y-4">
          {train.route.map((st, idx) => (
            <div key={st.stationCode} className="relative flex items-start gap-4">
              {idx !== train.route.length - 1 && <div className="absolute left-[15px] top-7 bottom-0 w-0.5 bg-stone-200" />}
              <div className={`z-10 grid h-8 w-8 shrink-0 place-items-center rounded-full text-xs font-bold border-2 ${
                st.isPassed ? 'bg-orange-600 text-white border-orange-600' : idx === 0 || idx === train.route.length - 1 ? 'bg-orange-600 text-white border-orange-600' : 'bg-white text-stone-600 border-stone-300'
              }`}>{idx + 1}</div>
              <div className="flex-1 rounded-2xl border border-stone-200 bg-white p-4 hover:border-orange-200 hover:shadow-sm transition-all">
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <div>
                    <div className="flex items-center gap-2">
                      <h4 className="font-bold text-stone-900">{st.stationName}</h4>
                      <span className="rounded-lg bg-orange-50 px-2 py-0.5 text-[10px] font-bold text-orange-700 border border-orange-200">{st.stationCode}</span>
                    </div>
                    <p className="text-xs text-stone-400 mt-0.5">{st.distanceKm} km {st.platform && `• Platform ${st.platform}`}</p>
                  </div>
                  <div className="text-right">
                    <div className="flex items-center gap-3 text-sm font-bold text-stone-700">
                      <span>Arr: {st.arrivalTime}</span>
                      <span>Dep: {st.departureTime}</span>
                    </div>
                    {st.haltMinutes > 0 && <p className="text-[11px] font-semibold text-orange-600 mt-0.5">Halt: {st.haltMinutes} mins</p>}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
        <div className="border-t border-stone-100 bg-stone-50/50 px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-2 text-xs text-stone-400">
            <Clock className="h-4 w-4 text-orange-600" />
            <span>IRCTC 2026 timetable</span>
          </div>
          <button onClick={onClose} className="btn-brand px-5 py-2.5 text-xs rounded-xl">Close</button>
        </div>
      </div>
    </div>
  );
};
